R,C=len(g),len(g[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if g[r][c]==0 and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c)); comp=[]
   while st:
    x,y=st.pop();comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=x+dx,y+dy
     if 0<=a<R and 0<=b<C and g[a][b]==0 and (a,b) not in seen: seen.add((a,b));st.append((a,b))
   comps.append(comp)
